import 'dart:convert';
import 'dart:io';
import '../../benchmark/value_store/tool_support.dart';

Future<void> main() async {
  const root = 'build/scoped-store-investigation';
  const out = '$root/screen-timing';
  if (Directory(out).existsSync()) throw StateError('Output exists');
  final first = readJson('$root/screen/manifest.json');
  final last = readJson('$root/batch-build/manifest.json');
  final manifest = {...first,
    'variant_sha256': <String, dynamic>{...first['variant_sha256'], ...last['variant_sha256']},
    'artifacts': <String, dynamic>{...first['artifacts'], ...last['artifacts']},
    'build_manifests': ['$root/screen/manifest.json', '$root/batch-build/manifest.json'],
    'runner_sha256': hashFile(Platform.script.toFilePath()),
    'build_note': 'Bucket draft syntax corrected before any timing. Three unchanged validated builds reused; bucket validation/build repeated separately.',
  };
  for (final variant in (manifest['variants'] as List).cast<String>()) {
    final build = variant == 'batch_buckets' ? '$root/batch-build' : '$root/screen';
    final receipts = jsonDecode(File('$build/receipts.json').readAsStringSync()) as List;
    for (final step in ['validation', 'jit-build', 'aot-build']) {
      if (!receipts.any((r) => r['job'] == '$variant-$step' && r['exit_code'] == 0)) {
        throw StateError('Missing successful $variant-$step');
      }
    }
